function toast(msg,type='info'){let h=$('#dapur-toast');if(!h){h=document.createElement('div');h.id='dapur-toast';h.className='toastbox';document.body.appendChild(h)}const n=document.createElement('div');n.className=`toast ${type}`;n.textContent=msg;h.appendChild(n);setTimeout(()=>n.remove(),3600)}
function meta(title,desc,url){document.title=title;for(const[n,v]of Object.entries({description:desc,'og:title':title,'og:description':desc,'og:url':url,'twitter:title':title,'twitter:description':desc})){let e=document.head.querySelector(`meta[name="${n}"]`)||document.head.querySelector(`meta[property="${n}"]`);if(!e){e=document.createElement('meta');e.setAttribute(n.startsWith('og:')?'property':'name',n);document.head.appendChild(e)}e.content=v}let c=document.head.querySelector('link[rel="canonical"]');if(c)c.href=url}
async function getUser(){for(let i=0;i<30&&!db();i++)await new Promise(r=>setTimeout(r,200));if(!db())throw Error('Koneksi Studihome belum siap.');const r=await db().auth.getUser();if(r.error&&!/auth session missing/i.test(r.error.message||''))throw r.error;return r.data?.user||null}
async function admin(){if(!user)return false;try{const r=await db().rpc('is_admin');return!r.error&&r.data===true}catch{return false}}
async function workspaceAccess(){if(!user)return false;const r=await db().rpc('has_creator_workspace_access');if(r.error)throw r.error;return r.data===true}
async function own(){if(!user)return null;const r=await db().from('creator_profiles').select('id,user_id,username,display_name,bio,avatar_url,whatsapp,location,contact_email,is_published,is_verified').eq('user_id',user.id).order('updated_at',{ascending:false}).limit(1);if(r.error)throw r.error;return r.data?.[0]||null}
async function byName(name){const clean=String(name||'').toLowerCase().trim();if(!/^[a-z0-9][a-z0-9-]{2,39}$/.test(clean))throw Error('Alamat Creator tidak valid.');const r=await db().from('creator_profiles').select('id,user_id,username,display_name,bio,avatar_url,whatsapp,location,contact_email,is_published,is_verified').ilike('username',clean).maybeSingle();if(r.error)throw r.error;if(!r.data)throw Error('Creator tidak ditemukan.');return r.data}
async function data(id){const [s,c,p]=await Promise.all([db().from('creator_services').select('id,title,description,price_from,price_to,delivery_days,is_active').eq('creator_id',id).order('created_at',{ascending:true}),db().from('creator_category_members').select('category_id,is_primary,ai_categories(id,name,slug)').eq('creator_id',id),db().from('creator_portfolios').select('id,title,description,media_type,media_url,is_active,sort_order').eq('creator_id',id).order('sort_order',{ascending:true}).order('created_at',{ascending:true})]);if(s.error)throw s.error;if(c.error)throw c.error;if(p.error)throw p.error;return{services:s.data||[],categories:c.data||[],portfolios:p.data||[]}}
async function featuredCreators(){if(!db())return[];const p=await db().from('creator_profiles').select('id,username,display_name,bio,avatar_url,is_published,is_verified,updated_at').eq('is_published',true).order('updated_at',{ascending:false}).limit(12);if(p.error)throw p.error;const profiles=p.data||[];if(!profiles.length)return[];const ids=profiles.map(x=>x.id);const m=await db().from('creator_category_members').select('creator_id,is_primary,ai_categories(id,name,slug)').in('creator_id',ids).order('is_primary',{ascending:false});if(m.error)throw m.error;const catMap=new Map();for(const row of m.data||[]){if(!catMap.has(row.creator_id)&&row.ai_categories)catMap.set(row.creator_id,row.ai_categories)}return profiles.map(x=>({...x,category:catMap.get(x.id)||null}))}
const sections=[['Menu','Kategori & keahlian.','Tunjukkan fokus keahlianmu.','<span aria-hidden="true" style="display:inline-block;vertical-align:middle;flex-shrink:0;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polygon points="16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76"/></svg></span>'],['Hidangan','Layanan & harga.','Jual layanan yang paling jago.','<span aria-hidden="true" style="display:inline-block;vertical-align:middle;flex-shrink:0;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 2v7c0 1.1.9 2 2 2h4a2 2 0 002-2V2"/><line x1="7" y1="2" x2="7" y2="22"/><path d="M17 2c-2 0-5 2.24-5 5v4c0 1.1.9 2 2 2h3V2"/></svg></span>'],['Ambalan','Karya & bukti.','Pamerin karya terbaikmu.','<span aria-hidden="true" style="display:inline-block;vertical-align:middle;flex-shrink:0;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/></svg></span>']];
function av(c){if(c?.avatar_url)return`<div class="avatar"><img src="${esc(c.avatar_url)}" alt="${esc(c.display_name||c.username||'Creator')}" loading="lazy"></div>`;const x=String(c?.display_name||c?.username||'Creator').trim().split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()||'✦';return`<div class="avatar">${esc(x)}</div>`}
function creatorAv(c){if(c?.avatar_url)return`<div class="creator-avatar"><img src="${esc(c.avatar_url)}" alt="${esc(c.display_name||c.username||'Creator')}" loading="lazy"></div>`;const x=String(c?.display_name||c?.username||'Creator').trim().split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase()||'✦';return`<div class="creator-avatar">${esc(x)}</div>`}
function headerNav(isAdmin=false){return`<nav class="dapur-quick-nav" aria-label="Navigasi cepat"><a href="/"><span aria-hidden="true" style="display:inline-block;vertical-align:middle;flex-shrink:0;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12l9-9 9 9"/><path d="M5 10v9a1 1 0 001 1h4v-5h4v5h4a1 1 0 001-1v-9"/></svg></span> Teras</a>${user&&!isAdmin?'<a class="primary-nav" href="/kamar"><span aria-hidden="true" style="display:inline-block;vertical-align:middle;flex-shrink:0;"><svg width="13" height="13" viewBox="0 0 512 512" fill="currentColor"><path d="M256 0c4.6 0 9.2 1 13.4 2.9L457.7 82.8c22 9.3 38.4 31 38.3 57.2c-.5 99.2-41.3 280.7-213.7 368.2c-16.7 8.2-36.8 8.2-53.5 0C57.3 420.7 16.5 239.2 16 140c-.1-26.2 16.3-47.9 38.3-57.2L242.7 2.9C246.9 1 251.4 0 256 0zm0 72l-42 16.6L256 116l42-27.4L256 72zM128 144c0-8.8 7.2-16 16-16h32c8.8 0 16 7.2 16 16v32c0 8.8-7.2 16-16 16h-32c-8.8 0-16-7.2-16-16V144zM320 144c0-8.8 7.2-16 16-16h32c8.8 0 16 7.2 16 16v32c0 8.8-7.2 16-16 16h-32c-8.8 0-16-7.2-16-16V144zM256 192c-53 0-96 43-96 96v128c0 17.7 14.3 32 32 32h128c17.7 0 32-14.3 32-32V288c0-53-43-96-96-96z"/></svg></span> Kamar</a>':''}${user&&isAdmin?'<a class="primary-nav" href="/admin"><span aria-hidden="true" style="display:inline-block;vertical-align:middle;flex-shrink:0;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l8 4v6c0 5.25-3.5 9.74-8 11-4.5-1.26-8-5.75-8-11V6l8-4z"/><path d="M9 12l2 2 4-4"/></svg></span> Admin</a>':''}${user&&isAdmin?'<button type="button" class="primary-nav" data-action="admin-panel"><span aria-hidden="true" style="display:inline-block;vertical-align:middle;flex-shrink:0;"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 01-2.83 2.83l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-4 0v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83-2.83l.06-.06A1.65 1.65 0 004.68 15a1.65 1.65 0 00-1.51-1H3a2 2 0 010-4h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 012.83-2.83l.06.06A1.65 1.65 0 009 4.68a1.65 1.65 0 001-1.51V3a2 2 0 014 0v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 2.83l-.06.06A1.65 1.65 0 0019.4 9a1.65 1.65 0 001.51 1H21a2 2 0 010 4h-.09a1.65 1.65 0 00-1.51 1z"/></svg></span> Kelola Semua</button>':''}</nav>`}
function mainCta(state){if(state==='admin')return'<a class="btn primary" href="/dapur/studihome">Manage Akun</a>';if(state==='creator')return`<a class="btn primary" href="/dapur/${encodeURIComponent(creator.username)}">Kelola Dapurku</a>`;if(state==='ready')return'<button class="btn primary" type="button" data-action="create">Mulai Membuat Dapur</button>';if(state==='premium')return'<a class="btn primary" href="/products">Lihat Produk Premium</a>';return'<button class="btn primary" type="button" data-action="auth" data-next="/dapur">Masuk / Daftar</button>'}
function creatorCard(c){return`<article class="creator-card">${creatorAv(c)}<div class="creator-meta"><div class="creator-cat">${esc(c.category?.name||'Creator')}</div><div class="creator-name">${esc(c.display_name||c.username)}</div><div class="creator-desc">${esc(c.bio||'Creator Studihome yang sedang menampilkan profil, layanan, dan karya.')}</div></div><a class="creator-link" href="/${encodeURIComponent(c.username)}">Profil</a></article>`}
function rootHtml(creators,state,isAdmin=false){const cards=creators.map(creatorCard).join('');return`<div class="dp"><div class="dc"><header class="top"><a class="brand" href="/"><span class="mark">✦</span><span>Studihome</span></a>${headerNav(isAdmin)}</header><main class="main"><section class="hero"><section class="card copy"><span class="eyebrow">Dapur</span><h1 class="title">Bikin brand-mu <em>lebih gampang ditemukan.</em></h1><p class="lead">Bantu pelanggan nemuin keahlianmu. Gampang, cepat, dan langsung keliatan.</p><div class="cta">${mainCta(state)}<a class="btn" href="/products">Temukan Promo</a></div><p class="note">${state==='admin'?'Akses Admin aktif. 🛠️':state==='creator'?'Dapurmu sudah ada! Tinggal rapikan, tampilin, dan share ke customer. 🚀':state==='ready'?'Kamu udah eligible jadi Creator. Tinggal buat Dapurmu! 🎉':state==='premium'?'Dapur Creator butuh Premium aktif.':'Masuk atau daftar buat mulai bikin Dapur Creator. ✨'}</p></section><section class="card visual"><div class="creator-kicker">Creator yang sedang tayang</div><h2 class="creator-title">Creator aktif yang sedang menyalakan kompor untuk pelanggan.</h2><p class="creator-note">Creator digital sedang menerima pesanan pelanggan.</p>${creators.length?`<div class="creator-viewport" aria-label="12 Creator aktif"><div class="creator-track"><div class="creator-set">${cards}</div><div class="creator-set" aria-hidden="true">${cards}</div></div></div>`:`<div class="creator-empty">Belum ada Creator yang sedang tayang. Begitu Creator mulai tayang, profil mereka akan muncul di sini.</div>`}</section></section><section id="cara-kerja" class="minis"><article class="card mini"><i>01</i><h3>Lebih gampang ditemukan</h3><p>Satu link untuk mempertemukan pelanggan dengan keahlianmu.</p></article><article class="card mini"><i>02</i><h3>Lebih cepat dipercaya</h3><p>Tampilkan layanan dan karya tanpa bikin orang muter-muter.</p></article><article class="card mini"><i>03</i><h3>Siap terima order</h3><p>Profil rapi, kontak jelas, pelanggan tinggal pilih.</p></article></section></main></div></div>`}
function workHtml(c,b,isAdmin=false){const done=[b.categories.length>0,b.services.length>0,b.portfolios.length>0],score=Math.round(done.filter(Boolean).length/3*100),publicUrl=`https://studihome.id/${encodeURIComponent(c.username)}`;return`<div class="dp"><div class="dc"><header class="top"><a class="brand" href="/"><span class="mark">✦</span><span>Studihome</span></a>${headerNav(isAdmin)}</header><main class="main"><section class="card workhero"><div class="profile">${av(c)}<div class="p-copy"><div class="p-kicker">Dapurku · Creator Workspace</div><h1>${esc(c.display_name||c.username)}</h1><div class="handle">@${esc(c.username)}</div><div class="badges"><span class="badge ${c.is_published?'ok':''}">${c.is_published?'Tayang':'Draft'}</span><span class="badge ${c.is_verified?'ok':''}">${c.is_verified?'Verified':'Belum verified'}</span></div></div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" type="button" data-action="profile">✏️ Edit Profil</button><a class="btn" href="/${encodeURIComponent(c.username)}" target="_blank">👁️ Lihat Profil</a></div></section><section class="card progress"><div class="prowl"><div><div class="protitle">Bikin Dapurmu siap ditemukan 🎯</div><div class="pronote">Mulai dari yang penting aja. Nggak harus selesai sekaligus kok!</div></div><strong class="score">${score}%</strong></div><div class="track"><span style="width:${score}%"></span></div></section><section class="card section"><div class="head"><div><h2>📦 Rapikan Dapurmu</h2><p>3 bagian utama biar profilmu makin kece dan gampang ditemukan.</p></div></div><div class="steps">${sections.map((x,i)=>`<button type="button" class="step ${done[i]?'done':''}" data-step="${i}"><div class="sttop"><span class="snum">${i+1}</span>${done[i]?'<span class="state">✓ Selesai</span>':'<span class="state">Langkah ${i+1}</span>'}</div><h3>${x[0]}</h3><p>${x[1]}</p><p class="step-desc">${x[2]}</p><span class="link">${done[i]?'Edit lagi →':'Mulai sekarang →'}</span></button>`).join('')}</div></section><section class="card canonical"><div class="head"><div><h2>🔗 Link siap dibagikan</h2><p>Kirim link ini ke customer. Workspace kamu tetap aman di <span style="white-space:nowrap">/dapur/${esc(c.username)}</span>.</p></div></div><div class="url"><div class="urlbox">${esc(publicUrl)}</div><button id="copy" class="btn primary" type="button">📋 Salin</button><button id="share" class="btn amber" type="button">📤 Bagikan</button></div></section></main></div></div>`}
function access(title,body,next,label='Masuk / Daftar'){return`<div class="dp"><div class="dc"><main class="main"><section class="card empty"><div class="emptyicon">✦</div><h1>${esc(title)}</h1><p>${esc(body)}</p><button class="btn primary" style="margin-top:18px" type="button" data-action="auth" data-next="${esc(next)}">${esc(label)}</button></section></main></div></div>`}
function ensureAuthModal(){if(authModal)return authModal;authModal=document.createElement('div');authModal.className='auth-overlay';authModal.id='dapur-auth-modal';authModal.style.cssText='display:none;position:fixed;inset:0;z-index:10000;align-items:center;justify-content:center;padding:16px;background:rgba(15,23,42,.58);backdrop-filter:blur(8px)';authModal.setAttribute('aria-hidden','true');authModal.inert=true;authModal.innerHTML='<div class="auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-modal-title" style="width:min(420px,100%);max-height:calc(100dvh - 32px);overflow:auto;border-radius:28px;background:#fff;border:1px solid #dbe5f5;box-shadow:0 30px 90px rgba(15,23,42,.25);padding:24px;position:relative;margin:auto"><button class="auth-close" type="button" data-action="auth-close" aria-label="Tutup" style="position:absolute;top:12px;right:12px;width:36px;height:36px;border:1px solid #bfdbfe;border-radius:12px;background:#dbeafe;color:#0f172a;font-weight:900;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:16px">&times;</button><div style="text-align:center;margin-top:8px"><div style="color:#EAB308;font-size:34px;font-weight:900;line-height:1;animation:spin-slow 8s linear infinite;display:inline-block">&#10022;</div><h2 id="auth-modal-title" style="margin:4px 0 0;color:#0f172a;font-size:20px;font-weight:900;text-align:center">Masuk ke Studihome</h2><p style="text-align:center;color:#64748b;font-size:11px;line-height:1.6;margin-top:4px">Akses Dapur Creator dan ruang pribadimu.</p></div><form id="login-form" style="margin-top:16px"><div class="auth-field"><label for="login-email">Email</label><input id="login-email" type="email" autocomplete="email" required placeholder="nama@email.com"></div><div class="auth-field"><label for="login-password">Kata Sandi</label><input id="login-password" type="password" autocomplete="current-password" required placeholder="&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;"></div><div style="text-align:right;margin-top:8px"><button type="button" data-action="auth-toggle" data-mode="forgot-password" style="border:0;background:none;color:#151c75;padding:0;font-size:11px;font-weight:700;cursor:pointer;text-decoration:underline">Lupa Password?</button></div><button class="auth-submit" type="submit">Masuk Sekarang</button><div class="auth-switch">Belum punya akun? <button type="button" data-action="auth-toggle" data-mode="register">Daftar Akun Baru</button></div></form><form id="register-form" style="display:none;margin-top:16px"><div class="auth-field"><label for="reg-name">Nama Lengkap <span style="color:#ef4444">*</span></label><input id="reg-name" type="text" autocomplete="name" required placeholder="Nama kamu"></div><div class="auth-field"><label for="reg-email">Email <span style="color:#ef4444">*</span></label><input id="reg-email" type="email" autocomplete="email" required placeholder="nama@email.com"></div><div class="auth-field"><label for="reg-phone">WhatsApp <span style="color:#ef4444">*</span></label><input id="reg-phone" type="tel" autocomplete="tel" inputmode="numeric" required placeholder="628123456789"><p style="color:#94a3b8;font-size:10px;margin-top:5px;line-height:1.5"><i class="fa-solid fa-circle-info" style="color:#60a5fa;margin-right:4px"></i> Wajib diawali <b style="color:#151c75">62</b>, ya &#8212; bukan 0 di depan. Contoh: <b style="color:#151c75">628123456789</b></p></div><div class="auth-field"><label for="reg-password">Kata Sandi <span style="color:#ef4444">*</span></label><input id="reg-password" type="password" autocomplete="new-password" required placeholder="&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;"></div><button class="auth-submit" type="submit" style="background:linear-gradient(135deg,#EAB308,#F59E0B);color:#0F172A">Buat Akun Sekarang</button><div class="auth-switch">Sudah punya akun? <button type="button" data-action="auth-toggle" data-mode="login">Masuk Ke Akun</button></div></form><form id="forgot-form" style="display:none;margin-top:16px"><div style="text-align:center;margin-bottom:8px"><div style="color:#f59e0b;font-size:24px;margin-bottom:8px"><i class="fa-solid fa-lock"></i></div><p style="color:#64748b;font-size:12px">Masukkan email akun Anda. Kami akan mengirimkan link untuk mengatur ulang kata sandi.</p></div><div class="auth-field"><label for="forgot-email">Email</label><input id="forgot-email" type="email" autocomplete="email" required placeholder="nama@email.com"></div><div id="forgot-success" style="display:none;text-align:center;padding:16px 0"><div style="color:#10b981;font-size:36px;margin-bottom:8px"><i class="fa-solid fa-circle-check"></i></div><p style="font-size:14px;font-weight:700;color:#334155">Email terkirim!</p><p style="font-size:12px;color:#64748b;margin-top:4px">Cek inbox email Anda untuk link reset password. Periksa juga folder Spam.</p></div><button type="submit" id="forgot-submit-btn" class="auth-submit">Kirim Link Reset</button><div class="auth-switch"><button type="button" data-action="auth-toggle" data-mode="login" style="border:0;background:none;color:#151c75;padding:0;font-size:12px;font-weight:700;cursor:pointer;text-decoration:underline"><i class="fa-solid fa-arrow-left" style="margin-right:4px"></i> Kembali ke Masuk</button></div></form></div>';document.body.appendChild(authModal);authModal.addEventListener('click',e=>{if(e.target===authModal)closeAuth()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&authModal)closeAuth()});authModal.querySelector('[data-action="auth-close"]').addEventListener('click',closeAuth);authModal.querySelectorAll('[data-action="auth-toggle"]').forEach(b=>b.addEventListener('click',()=>dapurSetAuthMode(b.dataset.mode)));authModal.querySelector('#login-form').addEventListener('submit',dapurLogin);authModal.querySelector('#register-form').addEventListener('submit',dapurRegister);authModal.querySelector('#forgot-form').addEventListener('submit',dapurForgotPassword);return authModal}
let authNext='/dapur';
function dapurSetAuthMode(mode){const lForm=authModal.querySelector('#login-form'),rForm=authModal.querySelector('#register-form'),fForm=authModal.querySelector('#forgot-form'),title=authModal.querySelector('#auth-modal-title');lForm.style.display='none';rForm.style.display='none';fForm.style.display='none';if(mode==='register'){rForm.style.display='block';title.textContent='Pendaftaran Akun Baru'}else if(mode==='forgot-password'){fForm.style.display='block';title.textContent='Lupa Password';const savedEmail=authModal.querySelector('#login-email')?.value||'';const forgotEmail=authModal.querySelector('#forgot-email');if(forgotEmail&&savedEmail)forgotEmail.value=savedEmail;const fs=authModal.querySelector('#forgot-success');if(fs)fs.style.display='none';const fb=authModal.querySelector('#forgot-submit-btn');if(fb)fb.style.display='block'}else{lForm.style.display='block';title.textContent='Masuk ke Studihome'}}
function openAuth(next){authNext=safeNext(next);const modal=ensureAuthModal();dapurSetAuthMode('login');const active=document.activeElement;if(active instanceof HTMLElement&&!modal.contains(active))authReturnFocus=active;modal.inert=false;modal.setAttribute('aria-hidden','false');modal.style.display='flex';requestAnimationFrame(()=>{const target=modal.querySelector('#login-email')||modal.querySelector('[data-action="auth-close"]');target?.focus()})}
function closeAuth(){if(!authModal)return;const active=document.activeElement;if(active instanceof HTMLElement&&authModal.contains(active))active.blur();authModal.inert=true;authModal.setAttribute('aria-hidden','true');authModal.style.display='none';const restore=authReturnFocus;authReturnFocus=null;if(restore instanceof HTMLElement&&restore.isConnected&&!restore.hasAttribute('disabled'))requestAnimationFrame(()=>restore.focus({preventScroll:true}))}
function validatePhoneForRegister(raw){const digits=String(raw||'').replace(/\D/g,'');if(!digits)return{ok:false,reason:'empty'};if(digits.startsWith('0'))return{ok:false,reason:'leading-zero'};if(!digits.startsWith('62'))return{ok:false,reason:'no-prefix'};return{ok:true,normalized:digits}}
async function dapurLogin(e){e.preventDefault();const form=e.currentTarget;const email=form.querySelector('#login-email').value.trim();const password=form.querySelector('#login-password').value;const submitBtn=form.querySelector('button[type="submit"]');if(!email||!password){toast('Masukkan email dan password.','error');return}if(password.length<6){toast('Kata sandi minimal 6 karakter.','error');form.querySelector('#login-password')?.focus();return}const origText=submitBtn.innerHTML;submitBtn.disabled=true;submitBtn.innerHTML='<i class="fa-solid fa-spinner fa-spin mr-1"></i> Memeriksa…';try{const c=db();if(!c?.auth)throw Error('Koneksi login belum siap.');const r=await c.auth.signInWithPassword({email,password});if(r.error)throw r.error;const current=await c.auth.getUser();const p=await c.from('profiles').select('status').eq('id',current.data.user.id).maybeSingle();if(p.error)throw p.error;if(String(p.data?.status||'active').toLowerCase()==='blocked'){await c.auth.signOut();throw Error('Akun Anda tidak aktif atau telah diblokir oleh Admin.')}closeAuth();location.replace(authNext)}catch(err){toast(err?.message||'Email atau kata sandi belum benar.','error')}finally{submitBtn.disabled=false;submitBtn.innerHTML=origText}}
async function dapurRegister(e){e.preventDefault();const form=e.currentTarget;const name=form.querySelector('#reg-name').value.trim();const email=form.querySelector('#reg-email').value.trim();const phoneRaw=form.querySelector('#reg-phone').value;const password=form.querySelector('#reg-password').value;const phoneCheck=validatePhoneForRegister(phoneRaw);if(!phoneCheck.ok){const msgs={empty:'Nomor WhatsApp-nya masih kosong nih. Yuk isi dulu, contoh: 628123456789 😊','leading-zero':'Ups, nomornya masih diawali 0! Ganti angka 0 paling depan jadi 62 ya — contoh: 628123456789 😉','no-prefix':'Hmm, nomor WhatsApp wajib diawali 62 (kode Indonesia) ya. Contoh: 628123456789 😉'};toast(msgs[phoneCheck.reason]||msgs['no-prefix'],'error');const phoneInput=form.querySelector('#reg-phone');if(phoneInput){phoneInput.focus();phoneInput.classList.add('ring-2','ring-rose-400','border-rose-300');setTimeout(()=>phoneInput.classList.remove('ring-2','ring-rose-400','border-rose-300'),2800)}return}const phone=phoneCheck.normalized;const submitBtn=form.querySelector('button[type="submit"]');const origText=submitBtn.innerHTML;submitBtn.disabled=true;submitBtn.innerHTML='<i class="fa-solid fa-spinner fa-spin mr-1"></i> Memproses…';try{const c=db();if(!c?.auth)throw Error('Koneksi daftar belum siap.');if(phone.length<8)throw Error('Nomor WhatsApp wajib diisi dengan benar.');const r=await c.auth.signUp({email,password,options:{data:{name,phone}}});if(r.error)throw r.error;dapurSetAuthMode('login');const loginEmail=authModal.querySelector('#login-email');if(loginEmail)loginEmail.value=email;if(r.data?.session){toast('Akun berhasil dibuat! 🎉','success')}else{toast('Akun dibuat. Cek email untuk konfirmasi, lalu masuk kembali.','success')}}catch(err){toast(err?.message||'Pendaftarannya belum berhasil. Coba cek lagi datanya, ya.','error')}finally{submitBtn.disabled=false;submitBtn.innerHTML=origText}}
async function dapurForgotPassword(e){e.preventDefault();const email=authModal.querySelector('#forgot-email').value.trim();if(!email){toast('Masukkan alamat email Anda.','error');return}try{const c=db();if(!c?.auth)throw Error('Koneksi belum siap.');await c.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/dapur'});const fs=authModal.querySelector('#forgot-success');if(fs)fs.style.display='block';const fb=authModal.querySelector('#forgot-submit-btn');if(fb)fb.style.display='none'}catch(err){toast(err?.message||'Gagal mengirim link reset. Coba lagi, ya.','error')}}
async function createCreator(){if(creating)return;creating=true;try{if(!user){openAuth('/dapur');return}if(!(await workspaceAccess())){location.assign('/products');return}const existing=await own();if(existing){location.assign(`/dapur/${encodeURIComponent(existing.username)}`);return}const r=await db().rpc('ensure_creator_draft');if(r.error)throw r.error;const username=String(r.data?.username||'').trim().toLowerCase();if(!/^[a-z0-9](?:[a-z0-9-]{1,38}[a-z0-9])?$/.test(username))throw Error('Username Creator otomatis tidak valid.');toast('Dapur Creator berhasil dibuat.','success');location.assign(`/dapur/${encodeURIComponent(username)}`)}catch(e){toast(e?.message||'Dapur belum bisa dibuat.','error')}finally{creating=false}}
function bindAuthActions(){document.querySelectorAll('[data-action="auth"]').forEach(b=>b.addEventListener('click',()=>openAuth(b.dataset.next||'/dapur')));document.querySelectorAll('[data-action="create"]').forEach(b=>b.addEventListener('click',createCreator));document.querySelectorAll('[data-action="admin-panel"]').forEach(b=>b.addEventListener('click',async()=>{try{await editor();const fn=window.AdminDapurUI?.adminPanel;if(typeof fn!=='function')throw Error('Panel admin belum tersedia.');await fn()}catch(e){toast(e?.message||'Panel admin belum bisa dibuka.','error')}}))}
async function editor(){if(window.AdminDapurUI)return;if(editorLoading)return editorLoading;editorLoading=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/dapur-editor.js?v=20260823noemail';s.onload=resolve;s.onerror=()=>reject(Error('Editor Dapur gagal dimuat.'));document.head.appendChild(s)});return editorLoading}
async function openEditor(name){try{await editor();const fn=window.AdminDapurUI?.[name];if(typeof fn!=='function')throw Error('Editor belum tersedia.');await fn(creator.id)}catch(e){toast(e?.message||'Form belum bisa dibuka.','error')}}
async function renderRoot(){creator=user?await own().catch(()=>null):null;const isAdmin=await admin();const access=user?await workspaceAccess().catch(()=>false):false;const state=isAdmin?'admin':creator?'creator':!user?'guest':access?'ready':'premium';const creators=await featuredCreators().catch(e=>{console.warn('[Dapur] featured creators unavailable:',e?.message||e);return[]});meta('Dapur Studihome — Creator Workspace','Bangun satu halaman brand untuk identitas, layanan, karya, dan kontak.','https://studihome.id/dapur');$('#app').innerHTML=rootHtml(creators,state,isAdmin);bindAuthActions();}
async function renderWorkspace(){if(!user){meta('Masuk untuk Mengelola Dapur — Studihome','Masuk untuk mengelola Creator workspace.','https://studihome.id/dapur/'+encodeURIComponent(slug()));$('#app').innerHTML=access('Masuk untuk mengelola Dapur','Workspace ini khusus pemilik Creator. Setelah masuk, kamu bisa mengatur identitas, fokus, layanan, dan karya.',path());bindAuthActions();return}const allowed=await workspaceAccess();if(!allowed){meta('Dapur Creator membutuhkan Premium — Studihome','Workspace Creator membutuhkan Premium aktif.','https://studihome.id/dapur/'+encodeURIComponent(slug()));$('#app').innerHTML=access('Dapur Creator membutuhkan Premium','Akses workspace membutuhkan Premium aktif. Setelah Premium aktif, kembali ke alamat Dapur Creator ini.','/products','Lihat Produk Premium');return}const isAdmin=await admin();const c=await byName(slug());if(!isAdmin&&c.user_id!==user.id){meta('Akses terbatas — Dapur Studihome','Workspace Creator ini hanya dapat dikelola pemilik atau Admin Studihome.','https://studihome.id/dapur/'+encodeURIComponent(c.username));$('#app').innerHTML=access('Dapur ini bukan milik akunmu','Demi keamanan, hanya pemilik Creator dan Admin Studihome yang dapat mengubah data.','/dapur','Kembali ke Dapur',);return}creator=c;bundle=await data(c.id);meta(`${c.display_name||c.username} — Dapur Studihome`,`Workspace pengelolaan profil, layanan, karya, dan fokus ${c.display_name||c.username}.`,`https://studihome.id/${encodeURIComponent(c.username)}`);$('#app').innerHTML=workHtml(c,bundle,isAdmin);bindAuthActions();bind()}
function bind(){document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>openEditor(['categories','service','portfolio'][Number(b.dataset.step)])));$('[data-action="profile"]')?.addEventListener('click',()=>openEditor('profile'));$('#copy')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(`https://studihome.id/${encodeURIComponent(creator.username)}`);toast('Link publik sudah disalin.','success')}catch{toast('Salin otomatis gagal. Salin link secara manual.','error')}});$('#share')?.addEventListener('click',async()=>{const url=`https://studihome.id/${encodeURIComponent(creator.username)}`;try{if(navigator.share)await navigator.share({title:`${creator.display_name||creator.username} — Studihome`,text:`Lihat profil ${creator.display_name||creator.username} di Studihome`,url});else{await navigator.clipboard.writeText(url);toast('Link publik disalin.','success')}}catch(e){if(e?.name!=='AbortError')toast('Bagikan belum berhasil. Link tetap bisa disalin.','error')}})}
async function render(){style();if(root())return renderRoot();if(slug())return renderWorkspace();meta('Dapur Studihome','Ruang Creator Studihome.','https://studihome.id/dapur');$('#app').innerHTML=access('Alamat Dapur tidak valid','Gunakan /dapur atau /dapur/{username}.','/dapur','Kembali ke Dapur');bindAuthActions()}
async function boot(){if(booting)return booting;booting=(async()=>{try{if(root()){const q=new URLSearchParams(location.search);if(q.has('intent')||q.has('next'))history.replaceState({},document.title,'/dapur')}user=await getUser();await render()}catch(e){console.error('[Studihome Dapur]',e);style();$('#app').innerHTML=access('Dapur belum dapat dimuat',e?.message||'Terjadi kendala saat memuat halaman.','/dapur','Muat ulang');bindAuthActions()}})();try{return await booting}finally{booting=null}}
window.App=window.App||{};window.App.ui=window.App.ui||{};window.App.ui.toast=toast;window.App.utils=window.App.utils||{};window.App.utils.escapeHtml=esc;window.Dapur={boot,render};
function start(){style();if(!$('#app'))return;boot();if(db()?.auth?.onAuthStateChange&&!window.__DapurAuthWired){window.__DapurAuthWired=true;db().auth.onAuthStateChange(()=>setTimeout(boot,80))}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
